import { useEffect, useRef } from 'react';
import styles from './Technologies.module.css';
import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';
import {
  CardAi,
  CardReliability,
  CardStrategy,
  CardProfit,
  CardData,
  CardProtection,
} from '../../components/technologies';

gsap.registerPlugin(ScrollTrigger);

export const Technologies = () => {
  const wrapperRef = useRef(null);
  const contentRef = useRef(null);

  const cardAiNumberRef = useRef(null);
  const cardAiImageRef = useRef(null);

  const cardReliabilityDescriptionRef = useRef(null);

  const cardStrategyNumberRef = useRef(null);
  const cardStrategyDescriptionRef = useRef(null);

  const cardDataNumberRef = useRef(null);

  const cardProtectionNumberRef = useRef(null);

  const cardProfitBlackBackground = useRef(null);

  useEffect(() => {
    let scrollTriggerInstance = null;

    function preventDefault(e) {
      e.preventDefault();
    }

    function disableScroll() {
      document.body.style.overflow = 'hidden';
      window.addEventListener('wheel', preventDefault, { passive: false });
      window.addEventListener('touchmove', preventDefault, { passive: false });
    }

    function enableScroll() {
      document.body.style.overflow = '';
      window.removeEventListener('wheel', preventDefault, { passive: false });
      window.removeEventListener('touchmove', preventDefault, { passive: false });
    }

    const ctx = gsap.context(() => {
      const container = contentRef.current;
      if (!container) return;

      const sections = gsap.utils.toArray(`.${styles.section}`, container);
      const totalScroll = container.scrollWidth - window.innerWidth;

      if (totalScroll <= 0) return;

      const sectionCount = sections.length;
      const snapPoints = sections.map((_, i) => i / (sectionCount - 1));

      scrollTriggerInstance = ScrollTrigger.create({
        trigger: wrapperRef.current,
        start: 'top1-=130 top-=0',
        end: `+=${totalScroll}`,
        scrub: true,
        pin: true,
        anticipatePin: 1,

        /*snap: {
          snapTo: snapPoints,
          duration: { min: 0.5, max: 1.5 },
          ease: 'power1.inOut',
        }, // авто-скролл
        onSnapStart: (self) => {
          disableScroll();

          // Мгновенный отклик
          const targetProgress = self.getClosestSnap(self.progress);
          const targetX = -totalScroll * targetProgress;
          const currentX = gsap.getProperty(container, 'x');
          const direction = targetX > currentX ? 1 : -1;

          gsap.set(container, { x: targetX + direction * 3 });

        },*/
        onSnapComplete: () => {
          enableScroll();
        },
        onUpdate: (self) => {
          // Не анимируем, если сейчас snap
          if (!self.isSnapping) {
            gsap.set(container, { x: -totalScroll * self.progress });
          }
        },
      });
    }, wrapperRef);

    return () => {
      ctx.revert();
      if (scrollTriggerInstance) scrollTriggerInstance.kill();
      enableScroll();
    };
  }, []);

  /*useEffect(() => {
    const wrapper = wrapperRef.current;
    if (wrapper) {
      wrapper.style.height = `${window.innerHeight}px`;
    }
  }, []);*/

  return (
    <>
      <section className={styles.wrapper} ref={wrapperRef}>
        <h1 className={styles.title}>Технологии</h1>
        <div className={styles.content} ref={contentRef}>
          <div className={styles.section}>
            <CardAi startRef={cardAiNumberRef} endRef={cardAiImageRef} />
          </div>
          <div className={styles.section}>
            <CardReliability startRef={cardReliabilityDescriptionRef}  endRef={cardAiImageRef} />
          </div>
          <div className={styles.section}>
            <CardStrategy
              startRef={cardReliabilityDescriptionRef}
              endRef={cardStrategyNumberRef}
              startRef2={cardStrategyDescriptionRef}
              endRef2={cardDataNumberRef}
            />
          </div>
          <div className={styles.section}>
            <CardProfit endRef={cardProfitBlackBackground} />
          </div>
          <div className={styles.section}>
            <CardData CardDataNumberRef={cardDataNumberRef} />
          </div>
          <div className={styles.section}>
            <CardProtection startRef={cardProtectionNumberRef} endRef={cardProfitBlackBackground} />
          </div>
        </div>
      </section>
    </>
  );
};
