import { createContext, useContext, useState } from "react";

// Создаем контекст
const DevElementsContext = createContext();

// Провайдер контекста
export const DevElementsProvider = ({ children }) => {
  const [showDevElements, setShowDevElements] = useState(true);

  return (
    <DevElementsContext.Provider
      value={{ showDevElements, setShowDevElements }}
    >
      {children}
    </DevElementsContext.Provider>
  );
};

// Хук для использования контекста
export const useDevElements = () => {
  return useContext(DevElementsContext);
};
