import React, { useEffect, useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { ToggleTabs } from '../../components/ToggleTabs';
import { ProfitabilityChart } from '../ProfitabilityChart';
import { fetchUserDataApi } from '../../../../../api/authApi';
import { DropdownTabs } from '../DropdownTabs';
import { EfficiencyTradesPage } from '../Efficiency';
import { calculateSharpeRatio } from '../../../../../utils/utils';

import styles from './Tracker.module.css';
import mainPageStyles from './MainPageStyles.module.css';

const timeframeMap = {
  День: 1,
  Неделя: 7,
  Месяц: 30,
  '6 Месяцев': 182,
  Год: 365,
  'Всё время': null,
};

const getKeyTradingStats = (positions = [], timeframe, initialDeposit = 1000) => {
  const now = Date.now();
  const days = timeframeMap[timeframe];
  const fromTime = days ? now - days * 24 * 60 * 60 * 1000 : 0;

  const filtered = positions.filter((pos) => {
    const timeMs = Number(pos.time) * 1000;
    return timeMs >= fromTime;
  });

  const totalProfit = positions.reduce((sum, pos) => sum + parseFloat(pos.profit || 0), 0);
  const timeframeProfit = filtered.reduce((sum, pos) => sum + parseFloat(pos.profit || 0), 0);

  return {
    timeframeProfitPercent: +((timeframeProfit / initialDeposit) * 100).toFixed(2),
    timeframeTrades: filtered.length,
    totalProfitPercent: +((totalProfit / initialDeposit) * 100).toFixed(2),
    totalTrades: positions.length,
  };
};

export const Tracker = ({ id, pageType = 'isDashboard', height, additionalData = [] }) => {
  // принять через props userAccount
  const [viewSelector, setViewSelector] = useState('График');
  const [timeframeSelector, setTimeframeSelector] = useState('День');
  const [benchmarkSelector, setBenchmarkSelector] = useState('-');
  const [strategySelector, setStrategySelector] = useState('VSA_ML');
  const [accountData, setAccountData] = useState(null);

  const reduxUserId = useSelector((state) => state.login?.user?.id);
  const userId = reduxUserId ?? localStorage.getItem('userId') ?? id;
  const terminalAccount = useSelector((state) => state.userData?.data?.accountInfo?.login);

  useEffect(() => {
    if (!userId) return;

    // Первый запрос
    fetchUserDataApi(userId).then((data) => setAccountData(data));
    // Интервал
    const interval = setInterval(() => {
      fetchUserDataApi(userId).then((data) => setAccountData(data));
    }, 5000000);

    return () => clearInterval(interval);
  }, [userId]);

  const initialDeposit = accountData?.data?.accountInfo?.balance || null; // или из accountData

  const positions = accountData?.data?.accountInfo?.positions_closed || [];

  const profits = positions.map((pos) => parseFloat(pos.profit));

  // Коэффициент Шарпа
  const sharpeRatio = calculateSharpeRatio(profits);

  // Вычисляем метрики на основе выбранного таймфрейма
  const { timeframeProfitPercent, timeframeTrades, totalProfitPercent, totalTrades } = useMemo(
    () => getKeyTradingStats(positions, timeframeSelector, initialDeposit),
    [positions, timeframeSelector, initialDeposit],
  );
  return (
    <>
      {pageType === 'isDashboard' ? (
        <div className={styles.container}>
          <div className={styles.header}>
            <h2 className={styles.tytle}>Трекер</h2>
          </div>

          <div className={styles.toggleContainer}>
            <ToggleTabs
              options={['График', 'Список']}
              onChange={(value) => setViewSelector(value)}
            />
            <ToggleTabs
              options={['День', 'Неделя', 'Месяц', '6 Месяцев', 'Год']}
              onChange={(value) => setTimeframeSelector(value)}
            />
          </div>
          <ProfitabilityChart
            accountData={accountData}
            timeframeSelector={timeframeSelector}
            viewSelector={viewSelector}
          />
        </div>
      ) : (
        <>
          <div className={mainPageStyles.infoBlock}>
            <div className={mainPageStyles.performanceBlock}>
              <EfficiencyTradesPage
                title={'Доходность'}
                /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
                firstValueLabel={'период'}
                firstValue={timeframeProfitPercent + '%'}
                secondValueLabel={'всего'}
                secondValue={totalProfitPercent + '%'}
              />

              <EfficiencyTradesPage
                title={'Коэффициент Шарпа'}
                /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
                firstValue={sharpeRatio.toFixed(2)}
                secondValue={null}
              />

              <EfficiencyTradesPage
                title={'Количество сделок'}
                /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
                firstValueLabel={'период'}
                firstValue={timeframeTrades}
                secondValueLabel={'всего'}
                secondValue={totalTrades}
              />
            </div>
            <div>
              <div className={styles.dropdownContainer}>
                <DropdownTabs
                  indicator={'#4A7F00'}
                  title={'Стратегии'}
                  options={['VSA_ML', 'ОБ30', 'TSA_ML']}
                  onChange={(value) => setStrategySelector(value)}
                />
                <DropdownTabs
                  indicator={'#147AFF'}
                  title={'Бенчмарк'}
                  options={['-', 'BTC']}
                  onChange={(value) => setBenchmarkSelector(value)}
                />
                <DropdownTabs
                  indicator={false}
                  title={'Период'}
                  options={['День', 'Неделя', 'Месяц', '6 Месяцев', 'Год']}
                  onChange={(value) => setTimeframeSelector(value)}
                />
              </div>
              <div className={mainPageStyles.container}>
                <div className={styles.infoBlock}>
                  <ProfitabilityChart
                    benchmarkSelector={benchmarkSelector}
                    strategySelector={strategySelector}
                    pageType={pageType}
                    accountData={accountData}
                    timeframeSelector={timeframeSelector}
                    viewSelector={viewSelector}
                    height={height}
                    additionalData={additionalData}
                  />
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </>
  );
};
