import { useEffect, useState, useMemo } from 'react';
import { CardConnector } from '../../../shared/ui/CardConnector';
import { getAdaptiveLength } from '../../../shared/lib/adaptive';
import styles from './CardProtection.module.css';

export const CardProtection = ({ startRef, endRef }) => {
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);
  const [windowHeight, setWindowHeight] = useState(window.innerHeight);

  useEffect(() => {
    const handleResize = () => {
      setWindowWidth(window.innerWidth);
      setWindowHeight(window.innerHeight);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const lenX1 = useMemo(
    () =>
      getAdaptiveLength({
        value: windowWidth,
        base: 2380,
        baseValue: 800,
        k: 1.0,
      }),
    [windowWidth],
  );

  const lenY1 = useMemo(
    () =>
      getAdaptiveLength({
        value: windowHeight,
        base: 1,
        baseValue: 660,
        k: 0.75,
      }),
    [windowHeight],
  );

  return (
    <div className={styles.box}>
      <div className={styles.wrapper}>
        <CardConnector
          startRef={startRef}
          startOffset={{ x: 0, y: 26 }}
          endRef={endRef}
          endOffset={{ x: 100, y: 0 }}
          type="l"
          lineColor="#ffc11c"
          strokeWidth={2}
        />
        <CardConnector
          startRef={endRef}
          startOffset={{ x: 100, y: -4 }}
          segments={[
            { length: 450, angle: 90 },
            { length: lenX1, angle: -90 },
            { length: lenY1, angle: 90 },
            { length: windowWidth, angle: 90 },
          ]}
          lineColor="#ffc11c"
          strokeWidth={2}
          zIndex={10}
        />

        <div className={styles.block}>
          <div className={styles.header}>
            <div ref={startRef} className={styles.number}>
              6.
            </div>
            <h2 className={styles.title}>Защита от отказов</h2>
          </div>
          <div className={styles.description}>
            В каждой стратегии предусмотрена многоуровневая система защиты от отказов в виде строгих
            правил установки трейлинг стоплоссов. Благодаря чему количество неудачных сделок
            существенно снижается.
          </div>
        </div>
      </div>
    </div>
  );
};
