import React, { useRef, useEffect } from 'react';
import gsap from 'gsap';


export const AnimatedLines = ({ lines, hoveredLineId, STOP_COUNT, windowSize, stepDelay }) => {
  const gradientRefs = useRef({});

  useEffect(() => {
    lines.forEach((line) => {
      const grad = gradientRefs.current[line.id];
      if (!grad) return;
      const stops = grad.querySelectorAll('stop');
      gsap.killTweensOf(stops);

      if (hoveredLineId === line.id) {
        let whiteSize = 1; // длина белого блика
        //let windowSize = 5; // длина всего луча
        let delay = 0;

        

for (let i = 0; i < STOP_COUNT - windowSize; i++) {
  gsap.to(stops, { stopColor: '#3D3D3D', duration: 0.01, delay: 0 });
  for (let j = 0; j < whiteSize; j++) {
    gsap.to(stops[i + j], { stopColor: '#FFD700', duration: 0.1, delay });
  }
  for (let j = whiteSize; j < windowSize; j++) {
    gsap.to(stops[i + j], { stopColor: '#ffffff', duration: 0.1, delay });
  }
  delay += stepDelay;
}


        // Выстрел лучом:
        // gsap.to(stops, { stopColor: '#3D3D3D', duration: 0.5, delay });
      } else {
        gsap.to(stops, { stopColor: '#3D3D3D', duration: 0.5 });
      }
    });
  }, [hoveredLineId, lines]);

  const renderStops = () => {
    const stops = [];
    for (let i = 0; i < STOP_COUNT; i++) {
      const offset = `${(i / (STOP_COUNT - 1)) * 100}%`;
      stops.push(<stop key={i} offset={offset} stopColor="#3D3D3D" />);
    }
    return stops;
  };
  

  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: 'absolute', left: 0, top: 0, pointerEvents: 'none' }}
    >
      <defs>
        {lines.map((line) => (
          <linearGradient
            key={line.id}
            id={`gradient-line-${line.id}`}
            gradientUnits="userSpaceOnUse"
            x1={line.x1}
            y1={line.y1}
            x2={line.x2}
            y2={line.y2}
            ref={(el) => (gradientRefs.current[line.id] = el)}
          >
            {renderStops()}
          </linearGradient>
        ))}
        <filter id="glow" x="-60%" y="-60%" width="220%" height="220%">
          <feDropShadow dx="0" dy="0" stdDeviation="8" floodColor="#FFD700" floodOpacity="0.05" />
          <feDropShadow dx="0" dy="2" stdDeviation="4" floodColor="#000000" floodOpacity="0.05" />
        </filter>
      </defs>
      {lines.map((line) => (
        <line
          key={line.id}
          x1={line.x1}
          y1={line.y1}
          x2={line.x2}
          y2={line.y2}
          stroke={`url(#gradient-line-${line.id})`}
          strokeWidth="2"
          filter={hoveredLineId === line.id ? 'url(#glow)' : undefined}
        />
      ))}
    </svg>
  );
};
