import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from './AccountInformation.module.css';
import { FileDownloader } from '../FileDownloader/FileDownloader';
import { BASE_URL } from '../../../../../helpers/config';

export const AccountInformation = ({ onSettingsClick, accountNumber, accountName }) => {
  const [number, setNumber] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    setNumber(accountNumber);
  }, [accountNumber]);

  useEffect(() => {
    const storedAccountNumber = localStorage.getItem({ accountName });
    setNumber(storedAccountNumber);
  }, []);

  const handleChange = () => {
    localStorage.removeItem({ accountName });
    setNumber(null);

    if (onSettingsClick) {
      onSettingsClick();
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.brokerInformation}>
        <div className={styles.brokerName}>Брокер RoboForex</div>
        <div className={styles.brokerAccount}>Счет {number}</div>
      </div>
      <div className={styles.settingsContainer}>
        <button className={styles.settings} onClick={handleChange}>
          настроить
        </button>
      </div>
      {number ? (
        <FileDownloader url={BASE_URL + `/download-advisor`} fileName={'stats_parsing.mq5'} />
      ) : null}
    </div>
  );
};
