export const nameValidation = {
  required: 'Имя обязательно',
  minLength: { value: 3, message: 'Имя слишком короткое' },
  maxLength: { value: 50, message: 'Имя слишком длинное' },
  noLeadingTrailingSpaces: (value) =>
    value.trim() === value || 'Имя не должно начинаться или заканчиваться пробелом',
};

export const emailValidation = {
  required: 'Email обязателен',
  pattern: {
    value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
    message: 'Некорректный email',
  },
  maxLength: 50,
  noLeadingTrailingSpaces: (value) =>
    value.trim() === value || 'E-mail не должен начинаться или заканчиваться пробелом',
};

export const passwordValidation = {
  required: 'Пароль обязателен',
  minLength: { value: 8, message: 'Пароль должен быть не менее 8 символов' },
  maxLength: { value: 50, message: 'Пароль слишком длинный' },
  noLeadingTrailingSpaces: (value) =>
    value.trim() === value || 'Пароль не должен начинаться или заканчиваться пробелом',
  //noSpaces: (value) => !/\s/.test(value) || 'Пароль не должен содержать пробелы',
  validate: {
    hasUpper: (value) =>
      /[A-ZА-Я]/.test(value) || 'Пароль должен содержать хотя бы одну заглавную букву',
    hasNumber: (value) => /\d/.test(value) || 'Пароль должен содержать хотя бы одну цифру',
    hasSpecial: (value) =>
      /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(value) ||
      'Пароль должен содержать хотя бы один специальный символ',
  },
};
