import React, { useState } from 'react';
import styles from './Efficiency.module.css';

export const Efficiency = ({ title, view, value }) => {
  const isActive = Boolean(value);
  const filteredValue = value ? value : 'N/A';
  return (
    <div className={styles.container}>
      <span className={styles.title}>{title}</span>
      <div className={isActive ? styles.performanceLightActive : styles.performanceLight}>
        <span className={styles.value}>{filteredValue}</span>
      </div>
    </div>
  );
};
