import { useEffect, useState, useMemo } from 'react';
import { CardConnector } from '../../../shared/ui/CardConnector';
import { getAdaptiveLength } from '../../../shared/lib/adaptive';
import styles from './CardStrategy.module.css';

export const CardStrategy = ({ startRef, endRef, startRef2, endRef2 }) => {
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);
  const [X2, setX2] = useState(window.innerWidth);

  useEffect(() => {
    const handleResize = () => {
      setX2(window.innerWidth);
      setWindowWidth(window.innerWidth);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  /*useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);*/

  const segmentLength = useMemo(() => {
    if (windowWidth < 1200) return 35 + (windowWidth - 1024) * 0.08; // малые ноуты
    if (windowWidth < 1440) return 47 + (windowWidth - 1200) * 0.05; // обычные ноуты
    if (windowWidth < 1680) return 65 + (windowWidth - 1440) * 0.05; // большие ноуты/мониторы
    if (windowWidth < 1920) return 85 + (windowWidth - 1680) * 0.05; // fullHD мониторы
    if (windowWidth < 2560) return 100 + (windowWidth - 1920) * 0.04; // 2K мониторы
    if (windowWidth < 3440) return 175 + (windowWidth - 2560) * 0.03; // ультравайды
    return 260 + (windowWidth - 3440) * 0.02; // 4K и больше
  }, [windowWidth]);

  const startLineLength = useMemo(() => {
    if (windowWidth < 1200) return 32.4 + (windowWidth - 1024) * 0.025;
    if (windowWidth < 1440) return 36.6 + (windowWidth - 1200) * 0.025;
    if (windowWidth < 1680) return 42.4 + (windowWidth - 1440) * 0.025;
    if (windowWidth < 1920) return 48.0 + (windowWidth - 1680) * 0.025;
    if (windowWidth < 2560) return 53.5 + (windowWidth - 1920) * 0.025;
    if (windowWidth < 3440) return 68.7 + (windowWidth - 2560) * 0.025;
    return 89.2 + (windowWidth - 3440) * 0.02;
  }, [windowWidth]);

  const lenX2 = useMemo(() => {
    if (windowWidth < 1200) return 850.0 - (windowWidth - 1024) * 0.5;
    if (windowWidth < 1440) return 740.0 - (windowWidth - 1200) * 0.5;
    if (windowWidth < 1680) return 610.0 - (windowWidth - 1440) * 0.5;
    if (windowWidth < 1920) return 470.0 - (windowWidth - 1680) * 0.5;
    if (windowWidth < 2560) return 310.0 - (windowWidth - 1920) * 0.5;
    if (windowWidth < 3440) return 740.0 - (windowWidth - 2560) * 0.5;
    return 740.0 - (windowWidth - 3440) * 0.05;
  }, [windowWidth]);

  console.log('lenX2', lenX2);

  return (
    <div className={styles.box}>
      <div className={styles.wrapper}>
        <CardConnector
          startRef={startRef}
          startLineLengthCoefficient={1.9}
          endRef={endRef}
          endLineLengthCoefficient={12.9}
          segmentLength={segmentLength}
          type="z"
          startOffset={{ x: 400, y: 182.9 }}
          endOffset={{ x: 0, y: 25 }}
          lineColor="#5B5B5B"
          strokeWidth={2}
        />

        <CardConnector
          type="z"
          startRef={startRef2}
          startLineLengthCoefficient={startLineLength}
          
          startOffset={{ x: 127, y: 231 }}
          endRef={endRef2}
          endLineLengthCoefficient={13}
          endOffset={{ x: 0, y: 25 }}
          zAngle={90}
          zIndex={1}
          lineColor="#5B5B5B"
          strokeWidth={2}
        />

        <div className={styles.block}>
          <div className={styles.header}>
            <div ref={endRef} className={styles.number}>
              3.
            </div>
            <h2 className={styles.title}>Стратегии</h2>
          </div>
          <div ref={startRef2} className={styles.description}>
            Проектирование стратегий проводилось с использованием трейдерских компетенций команды и
            обладают глубокой проработкой механики движения цен
          </div>
        </div>
      </div>
    </div>
  );
};
